import {timelineFrameAt,timelineFrameTime} from './timeline-rate.js';

export const sequenceClockSources=['game','unscaled','manual','playEveryFrame','external'];
export function validSequenceClock(value){return value===undefined||!!value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).every(k=>['source','secondsPerFrame'].includes(k))&&(value.source===undefined||sequenceClockSources.includes(value.source))&&(value.secondsPerFrame===undefined||Number.isFinite(value.secondsPerFrame)&&value.secondsPerFrame>=.001&&value.secondsPerFrame<=60);}
export function sequenceClockSettings(data){if(!validSequenceClock(data.playbackClock))throw Error('시퀀스 재생 시계 설정을 확인하세요.');return {source:data.playbackClock?.source??'game',secondsPerFrame:data.playbackClock?.secondsPerFrame??timelineFrameTime(data,1)};}
export function sequenceClockDelta(state,delta,unscaledDelta=delta){
  const clock=state.clock;if(state.paused||state.seek){clock.held=0;return 0;}
  if(clock.source==='manual'||clock.source==='external')return 0;
  if(clock.source==='game'||clock.source==='unscaled')return (clock.source==='game'?delta:unscaledDelta)*state.data.rate;
  clock.held+=unscaledDelta*state.data.rate;
  if(clock.held+Number.EPSILON*8<clock.secondsPerFrame)return 0;
  // A slow update holds the next frame; it never skips or catches up in a burst.
  clock.held=0;return Math.max(0,Math.min(state.data.length,timelineFrameTime(state.data,timelineFrameAt(state.data,state.time,'floor')+1))-state.time);
}
export function sequenceExternalDelta(state,seconds){const clock=state.clock;if(clock.source!=='external'||!Number.isFinite(seconds)||Math.abs(seconds)>2**40)throw Error('외부 시계와 유한한 초 범위(±2^40)를 확인하세요.');const previous=clock.externalTime,rebase=clock.externalRebase||state.paused||state.seek||previous===undefined,backwards=previous!==undefined&&seconds<previous,delta=rebase||backwards?0:(seconds-previous)*state.data.rate;if(delta/state.data.length>255)throw Error('외부 시계 간격이 너무 커요. 외부 시계를 초기화한 뒤 다시 공급하세요.');if(backwards)clock.externalDiscontinuities=(clock.externalDiscontinuities||0)+1;clock.externalTime=seconds;clock.externalRebase=false;return delta;}
export function resetSequenceExternal(clock,clear=false){clock.externalRebase=true;if(clear){delete clock.externalTime;clock.externalDiscontinuities=0;}}
export function sequenceExternalFrameTime(frame,numerator,denominator){if(!Number.isInteger(frame)||frame<0||frame>2147483647||![numerator,denominator].every(v=>Number.isInteger(v)&&v>0&&v<=2147483647)||numerator/denominator<1||numerator/denominator>240)throw Error('외부 프레임과 1~240 FPS 분수 정수 범위를 확인하세요.');return frame*denominator/numerator;}
export const sequenceClockContract={field:'playbackClock',optional:true,sources:sequenceClockSources,defaultSource:'game',secondsPerFrame:{minimum:.001,maximum:60,default:'one display frame in seconds'},runtime:'SetClockSource/GetClockSource/SetSecondsPerFrame/GetSecondsPerFrame; Advance evaluates a nonnegative manual delta with playback rate and crossed events; Evaluate samples current time without events. Pause blocks Advance.',external:{api:['SetExternalTime(double seconds)','SetExternalFrame(int frame,int numerator,int denominator)','ResetExternalTime','GetExternalTime(double)','HasExternalTime'],sampling:'Push on the director. First sample anchors; subsequent nonnegative timestamp differences evaluate immediately through existing event/loop/nested/restore path, multiplied by playback rate. No input holds. Native commands retain the existing queue/frame barrier.',discontinuities:'Backwards timestamps reanchor silently and increment debug count. Pause/resume, Seek/Evaluate and source changes require a new anchor. Reset clears last timestamp/count. Too-large forward gaps reject before mutation; explicit Reset opts into a fresh anchor.',precision:'Finite seconds within ±2^40; C++ setter/getter use double. Frame source is int32 and independent rational1..240 FPS, without retiming authored keys.',diagnostics:['externalTime','externalTimeReady','externalDiscontinuities'],scope:'External push adapter only. No device I/O, wall-clock polling, pull callback registry, PCM synchronization or hardware genlock. External audio is parked/force-seeked.'},playEveryFrame:'One next display frame at most per active VM update after unscaled elapsed hold; slow updates discard excess elapsed time. Child sections inherit root time. No global VM pause bypass.',storage:'Settings never retime stored seconds or change display/capture/engine cadence.',remaining:['External audio/timecode/RTC/genlock device integration and pull providers','Independent child/channel time inheritance']};
